try {
  $root=[IO.Path]::GetFullPath((Join-Path (Get-Location) '../wtc-WP-KERNEL-012/src/frontend/handshake_native/src'))
  $cursor=$root
  while($cursor){
    $item=Get-Item -LiteralPath $cursor -Force
    if(!$item.PSIsContainer -or (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)){throw 'nonordinary directory'}
    $cursor=[IO.Path]::GetDirectoryName($cursor)
  }
  $entries=@(Get-ChildItem -LiteralPath $root -Force)
  if($entries.Count -gt 128){throw 'entry cap'}
  $rows=[Collections.Generic.List[object]]::new()
  foreach($entry in ($entries | Sort-Object -Property Name -CaseSensitive)){
    if(($entry.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0){throw 'reparse entry'}
    $kind=if($entry.PSIsContainer){'directory'}else{'file'}
    $bytes=if($entry.PSIsContainer){$null}else{$entry.Length}
    $rows.Add([ordered]@{name=$entry.Name;kind=$kind;bytes=$bytes})
  }
  $payload=([ordered]@{root=$root;recursive=$false;sourceContentRead=$false;entries=$rows;interpretation='Immediate path candidates only; module mapping and HandshakeApp definition/accessor remain unproven'} | ConvertTo-Json -Depth 5 -Compress)
  $utf8=[Text.UTF8Encoding]::new($false,$true)
