  $sha=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($encoded)).ToLowerInvariant()
  $nl=[string][char]10
  $frame='DIRECTORY INVENTORY 1/1 BEGIN'+$nl+"METADATA sha256=$sha bytes=$($encoded.Length)"+$nl+$payload+$nl+'DIRECTORY INVENTORY 1/1 COMPLETE'+$nl+'LOCAL INVENTORY END COMPLETE'
  if($frame.Length -gt 16000){throw 'complete frame cap'}
  [Console]::Out.WriteLine($frame)
  [Console]::Out.Flush()
  exit 0
}catch{
  $err='STOP '+$_.Exception.Message
  [Console]::Error.WriteLine($err.Substring(0,[Math]::Min(500,$err.Length)))
  [Console]::Error.Flush()
  exit 1
}

