function Confirm-InventoryReceipt([string]$receipt){
  if($receipt.Length -gt 16000 -or $receipt -match '[^\x20-\x7e\r\n]'){throw 'receipt representation'}
  $body=$receipt -replace '\r?\n$',''
  $lines=@($body -split '\r?\n')
  if($lines.Count -lt 7 -or $lines[0] -cne 'INVENTORY_V2 BEGIN' -or $lines[-1] -cne 'INVENTORY_V2 END'){throw 'receipt frame'}
  if($lines[1] -cnotmatch '^BYTES ([0-9]+)$'){throw 'receipt bytes'};$n=[int]$Matches[1]
  if($lines[2] -cnotmatch '^SHA256 ([0-9a-f]{64})$'){throw 'receipt hash'};$hash=$Matches[1]
  if($lines[3] -cnotmatch '^ENTRIES ([0-9]+)$'){throw 'receipt entries'};$count=[int]$Matches[1]
  if($lines[4] -cnotmatch '^CHUNKS ([0-9]+)$'){throw 'receipt chunks'};$chunks=[int]$Matches[1]
  if($n -gt 12288 -or $count -gt 128 -or $chunks -lt 1 -or $chunks -gt 256 -or $lines.Count -ne $chunks+6){throw 'receipt caps/count'}
  $encoded=''
  for($i=0;$i -lt $chunks;$i++){
    $prefix='DATA '+($i+1).ToString('D3')+' '
    if(!$lines[$i+5].StartsWith($prefix,[StringComparison]::Ordinal)){throw 'receipt sequence'}
    $part=$lines[$i+5].Substring($prefix.Length)
    if($part.Length -lt 1 -or $part.Length -gt 64 -or $part -cnotmatch '^[A-Za-z0-9+/]*={0,2}$'){throw 'receipt chunk'}
    if($i -lt $chunks-1 -and $part.Length -ne 64){throw 'receipt interior chunk'}
    $encoded+=$part
  }
  $bytes=[Convert]::FromBase64String($encoded)
  if([Convert]::ToBase64String($bytes) -cne $encoded -or $bytes.Length -ne $n){throw 'receipt encoding/length'}
  $observed=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($bytes)).ToLowerInvariant()
  if($observed -cne $hash){throw 'receipt hash mismatch'}
  $utf8=[Text.UTF8Encoding]::new($false,$true)
  $json=$utf8.GetString($bytes)
  if([Convert]::ToBase64String($utf8.GetBytes($json)) -cne $encoded){throw 'receipt UTF8 roundtrip'}
  $value=$json|ConvertFrom-Json
  $expected=[IO.Path]::GetFullPath((Join-Path (Get-Location) '../wtc-WP-KERNEL-012/src/frontend/handshake_native/src'))
  if($value.root -cne $expected -or $value.recursive -ne $false -or $value.sourceContentRead -ne $false -or @($value.entries).Count -ne $count){throw 'receipt scope'}
  foreach($row in $value.entries){
    if($row.name -isnot [string] -or !$row.name.Length -or $row.name.Contains('/') -or $row.name.Contains('\') -or $row.kind -cnotin @('file','directory')){throw 'receipt row'}
    if($row.kind -ceq 'directory' -and $null -ne $row.bytes){throw 'receipt directory'}
    if($row.kind -ceq 'file' -and ($null -eq $row.bytes -or $row.bytes -lt 0)){throw 'receipt file'}
  }
  return $json
}
