try {
  $base=[IO.Path]::GetFullPath((Join-Path (Get-Location) '../wtc-WP-KERNEL-012'))
  $specs=@(
    @{path='src/frontend/handshake_native/src/lib.rs';bytes=9964;mode='module'},
    @{path='src/frontend/handshake_native/src/app.rs';bytes=2072915;mode='owner-reference'}
  )
  $snapshots=[Collections.Generic.List[object]]::new();$totalRaw=0
  foreach($spec in $specs){
    $path=[IO.Path]::GetFullPath((Join-Path $base $spec.path))
    $cursor=$path;$first=$true
    while($cursor){
      $item=Get-Item -LiteralPath $cursor -Force
      if(($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0 -or ($first -and $item.PSIsContainer) -or (!$first -and !$item.PSIsContainer)){throw 'nonordinary source path'}
      $cursor=[IO.Path]::GetDirectoryName($cursor);$first=$false
    }
    $raw=[IO.File]::ReadAllBytes($path)
    if($raw.Length -ne $spec.bytes){throw 'inventory size changed'}
    $totalRaw+=$raw.Length
    if($totalRaw -gt 3145728){throw 'raw snapshot cap'}
    $sha=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($raw)).ToLowerInvariant()
    $snapshots.Add(@{spec=$spec;raw=$raw;sha256=$sha;rawBytes=$raw.Length})
  }
  $utf8=[Text.UTF8Encoding]::new($false,$true)
  $files=[Collections.Generic.List[object]]::new()
  $locationCount=0;$selectedCount=0;$sourceBytes=0
  foreach($snapshot in $snapshots){
    $text=$utf8.GetString($snapshot.raw)
    if([Convert]::ToBase64String($snapshot.raw) -cne [Convert]::ToBase64String($utf8.GetBytes($text))){throw 'source UTF8 roundtrip'}
    $lines=[regex]::Matches($text,'[^\n]*\n|[^\n]+$')
    $chosen=[Collections.Generic.SortedSet[int]]::new();$hits=[Collections.Generic.List[object]]::new()
    for($i=0;$i -lt $lines.Count;$i++){
      $line=$lines[$i].Value;$kind=$null
      if($snapshot.spec.mode -ceq 'module'){
        if($line -match '^\s*(?:pub(?:\([^)]*\))?\s+)?mod\s+app\b'){$kind='literal-app-module-declaration'}
      }else{
        if($line.Contains('AtelierPanel')){$kind='literal-AtelierPanel-reference'}
        elseif($line -match '^\s*(?:pub(?:\([^)]*\))?\s+)?struct\s+HandshakeApp\b'){$kind='HandshakeApp-declaration'}
      }
      if(!$kind){continue}
      $hits.Add(@{line=$i+1;kind=$kind});$locationCount++
      $null=$chosen.Add($i+1)
      for($j=[Math]::Max(0,$i-2);$j -le [Math]::Min($lines.Count-1,$i+2);$j++){
        if($lines[$j].Value -match '^\s*(?:use\s+.*\bAtelierPanel\b|#\s*\[\s*path\s*=)'){$null=$chosen.Add($j+1)}
      }
    }
    $selected=[Collections.Generic.List[object]]::new()
    foreach($n in $chosen){
      $selectedCount++;$sourceBytes+=$utf8.GetByteCount($lines[$n-1].Value)
      $selected.Add(@{number=$n;text=$lines[$n-1].Value})
    }
    if($locationCount -gt 32 -or $selectedCount -gt 128 -or $sourceBytes -gt 24576){throw 'selected source cap'}
    $files.Add([ordered]@{path=$snapshot.spec.path;rawBytes=$snapshot.rawBytes;sha256=$snapshot.sha256;guardOrigin='measured-same-buffer-before-decode';byteRoundtrip=$true;locations=$hits;lines=$selected})
  }
  $payload=([ordered]@{kind='source-header-reference-snapshot';files=$files;interpretation='Candidate linkage discovery only; prior source SHA UNKNOWN, no source compatibility/accessor/runtime claim; missing matches remain scoped gaps'} | ConvertTo-Json -Depth 10 -Compress)
  $encoded=$utf8.GetBytes($payload)
  if($encoded.Length -gt 12288){throw 'serialized payload cap'}
  $sha=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($encoded)).ToLowerInvariant()
  $base64=[Convert]::ToBase64String($encoded);$chunks=[int][Math]::Ceiling($base64.Length/64.0)
  if($chunks -lt 1 -or $chunks -gt 256){throw 'chunk cap'}
  $parts=[Collections.Generic.List[string]]::new()
  $parts.Add('INVENTORY_V2 BEGIN');$parts.Add("BYTES $($encoded.Length)");$parts.Add("SHA256 $sha");$parts.Add("ENTRIES $selectedCount");$parts.Add("CHUNKS $chunks")
  for($i=0;$i -lt $chunks;$i++){
    $offset=$i*64
    $parts.Add('DATA '+($i+1).ToString('D3')+' '+$base64.Substring($offset,[Math]::Min(64,$base64.Length-$offset)))
  }
  $parts.Add('INVENTORY_V2 END');$frame=$parts -join ([string][char]10)
  if($frame.Length -gt 16000){throw 'complete frame cap'}
  $checked=Confirm-InventoryReceipt $frame
  if($checked -cne $payload){throw 'producer roundtrip'}
  [Console]::Out.WriteLine($frame);[Console]::Out.Flush();exit 0
}catch{
  $err='STOP '+$_.Exception.Message
  [Console]::Error.WriteLine($err.Substring(0,[Math]::Min(500,$err.Length)))
  [Console]::Error.Flush();exit 1
}

